class AlarmMgmtInterface21B(object):

    def __init__(self):

        self._allowed_alarm_validators = []

    def get_active_alarms(self, severity=None, timeout=10):
        """
        Get a list of active alarms.

        :param string severity: Alarm severity (critical, major, minor or warning)
        :param int timeout: Timeout for the operation.
        :return list: List of active alarms. More details (content of requestMessage is returned data):
                        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-abnormalities.html
        """
        active_alarms = self._get_abnormalities("currentAlarms", severity, False, timeout)
        if active_alarms is None:
            raise DataNotAvailable("ActiveAlarms data has not been provided by M-Plane.")
        return active_alarms

    def get_active_alarms_number(self, timeout=10):
        """
        Get a number of active alarms. It is a length of active alarms list.

        :param int timeout: Timeout for the operation.
        :return int: Number of active alarms. More details (content of requestMessage is returned data):
                     https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getActiveAlarms.html
        """
        return len(self.get_active_alarms(timeout=timeout))

    def get_historic_alarms(self, severity=None, load_history=False, timeout=10):
        """
        Get a list of historical alarms.

        :param string severity: Alarm severity (critical, major, minor or warning)
        :param boolean load_history: load entire BTS history (may significantly extent time for request)
        :param int timeout: Timeout for the operation.
        :return list: List of historical alarms. More details (content of requestMessage is returned data):
                        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-abnormalities.html
        """

        historic_alarms = self._get_abnormalities("historicalAlarms", severity, load_history, timeout)
        if historic_alarms is None:
            raise DataNotAvailable("Historic alarms data has not been provided by M-Plane.")
        return historic_alarms

    def get_historic_alarms_number(self, timeout=10):
        """
        Get a list of historical alarms. It is a length of historical alarms list.

        :param int timeout: Timeout for the operation.
        :return int: Number of historical alarms. More details (content of requestMessage is returned data):
                        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-abnormalities.html
        """
        return len(self.get_historic_alarms(timeout=timeout))

    def get_raw_alarm_history_file(self, timeout=120, detailed_output=False):
        """
        Get Raw Alarm History file content.

        :param int timeout: (optional) Timeout for the operation. Defaults set to 120s.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return: Union[str,dict] file content or whole dict response if detailed_output is set to True.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getRawAlarmHistory.html
        """

        response = self._api_client.execute_customer_procedure(name="getRawAlarmHistory",
                                                               parameters={},
                                                               timeout=timeout)

        rah = response.get(self._provided_content.output_file_content)

        if not rah:
            raise DataNotAvailable("RAH file content has not been provided by M-Plane.")

        return response if detailed_output else base64.b64decode(rah).decode('utf-8')

    def collect_raw_alarm_history_file(self, target_file_name, timeout=120):
        """
        Collect raw alarm history file and save in provided path.

        :param str target_file_name: target RAH filename
        :param int timeout: (optional) Timeout for the operation. Defaults set to 120s.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-getRawAlarmHistory.html
        """
        self._api_client.execute_customer_procedure(name="getRawAlarmHistory",
                                                    parameters={},
                                                    timeout=timeout,
                                                    output_file_name=target_file_name)

